import json, subprocess, sys, os

ENTRY = '/app/submission/entry.py'

def run(obj, raw=None):
    data = raw if raw is not None else json.dumps(obj).encode()
    p = subprocess.run([sys.executable, '-I', ENTRY], input=data,
                       capture_output=True, cwd='/app/submission')
    assert p.returncode == 0, (p.returncode, p.stderr[-2000:])
    try:
        return json.loads(p.stdout.decode()), p.stderr.decode()
    except Exception as e:
        raise AssertionError('bad output %r: %s' % (p.stdout[:500], e))

INVALID = {"error": "INVALID_INPUT"}

def cfg(**kw):
    c = {"early": False, "overlap": "reject", "buffer_packets": 4, "idle_ms": 0,
         "max_streams_bidi": 4, "max_streams_uni": 4, "max_stream_data": 64,
         "max_data": 4611686018427387903, "crypto_limit": 64,
         "sent": {"I": [], "H": [], "A": []}}
    c.update(kw)
    return c

def doc(*traces):
    return {"version": 1, "traces": list(traces)}

def trace(tid, events, **kw):
    return {"id": tid, "config": cfg(**kw), "events": list(events)}

def dg(t, pkts, size=1200):
    return {"t": t, "op": "datagram", "bytes": size, "packets": pkts}

def pk(level, pn, frames, auth=True):
    return {"level": level, "pn": pn, "auth": auth, "frames": frames}

def key(t, level, action):
    return {"t": t, "op": "key", "level": level, "action": action}

def tick(t):
    return {"t": t, "op": "tick"}

FAILS = []
N = 0

def check(name, got, want):
    global N
    N += 1
    if got != want:
        FAILS.append(name)
        print('FAIL', name)
        print('  got :', json.dumps(got)[:3000])
        print('  want:', json.dumps(want)[:3000])

def summary():
    print('%d checks, %d failures: %s' % (N, len(FAILS), FAILS))
PYEOF
echo done
